use std::fmt;
use std::io::{self, Read};
use std::str::FromStr;

// ---- the options parser from practice 6.05 ----

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum Level {
    Debug,
    Info,
    Warn,
    Error,
}

impl FromStr for Level {
    type Err = ();
    fn from_str(s: &str) -> Result<Level, ()> {
        match s.to_ascii_lowercase().as_str() {
            "debug" => Ok(Level::Debug),
            "info" => Ok(Level::Info),
            "warn" => Ok(Level::Warn),
            "error" => Ok(Level::Error),
            _ => Err(()),
        }
    }
}

#[derive(Debug, PartialEq)]
struct Options {
    level: Level,
    top: usize,
    sources: Vec<String>,
    help: bool,
}

#[derive(Debug, PartialEq)]
enum ArgError {
    Unknown(String),
    MissingValue(String),
    BadValue { option: String, value: String },
}

impl fmt::Display for ArgError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ArgError::Unknown(a) => write!(f, "unknown argument '{a}'"),
            ArgError::MissingValue(o) => write!(f, "{o} needs a value"),
            ArgError::BadValue { option, value } => write!(f, "invalid value '{value}' for {option}"),
        }
    }
}

fn parse_args(args: &[&str]) -> Result<Options, ArgError> {
    let mut opts = Options { level: Level::Debug, top: 5, sources: Vec::new(), help: false };
    let mut i = 0;
    while i < args.len() {
        let arg = args[i];
        let (name, inline) = match arg.split_once('=') {
            Some((n, v)) if n.starts_with("--") => (n, Some(v.to_string())),
            _ => (arg, None),
        };
        let mut value = |i: &mut usize| -> Result<String, ArgError> {
            if let Some(v) = inline.clone() {
                return Ok(v);
            }
            *i += 1;
            args.get(*i).map(|v| v.to_string()).ok_or_else(|| ArgError::MissingValue(name.to_string()))
        };
        let bad = |v: &str| ArgError::BadValue { option: name.to_string(), value: v.to_string() };
        match name {
            "-h" | "--help" => opts.help = true,
            "--level" => {
                let v = value(&mut i)?;
                opts.level = v.parse().map_err(|_| bad(&v))?;
            }
            "--top" => {
                let v = value(&mut i)?;
                opts.top = match v.parse::<usize>() {
                    Ok(n) if n >= 1 => n,
                    _ => return Err(bad(&v)),
                };
            }
            "--source" => {
                let v = value(&mut i)?;
                opts.sources.push(v);
            }
            _ => return Err(ArgError::Unknown(arg.to_string())),
        }
        i += 1;
    }
    Ok(opts)
}

