use std::collections::{BTreeMap, HashMap};
use std::fmt;
use std::io::{self, BufWriter, Read, Write};
use std::str::FromStr;

// ---- the options parser from practice 6.05 ----

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum Level {
    Debug,
    Info,
    Warn,
    Error,
}

impl FromStr for Level {
    type Err = ();
    fn from_str(s: &str) -> Result<Level, ()> {
        match s.to_ascii_lowercase().as_str() {
            "debug" => Ok(Level::Debug),
            "info" => Ok(Level::Info),
            "warn" => Ok(Level::Warn),
            "error" => Ok(Level::Error),
            _ => Err(()),
        }
    }
}

#[derive(Debug, PartialEq)]
struct Options {
    level: Level,
    top: usize,
    sources: Vec<String>,
    help: bool,
}

#[derive(Debug, PartialEq)]
enum ArgError {
    Unknown(String),
    MissingValue(String),
    BadValue { option: String, value: String },
}

impl fmt::Display for ArgError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ArgError::Unknown(a) => write!(f, "unknown argument '{a}'"),
            ArgError::MissingValue(o) => write!(f, "{o} needs a value"),
            ArgError::BadValue { option, value } => write!(f, "invalid value '{value}' for {option}"),
        }
    }
}

fn parse_args(args: &[&str]) -> Result<Options, ArgError> {
    let mut opts = Options { level: Level::Debug, top: 5, sources: Vec::new(), help: false };
    let mut i = 0;
    while i < args.len() {
        let arg = args[i];
        let (name, inline) = match arg.split_once('=') {
            Some((n, v)) if n.starts_with("--") => (n, Some(v.to_string())),
            _ => (arg, None),
        };
        let mut value = |i: &mut usize| -> Result<String, ArgError> {
            if let Some(v) = inline.clone() {
                return Ok(v);
            }
            *i += 1;
            args.get(*i).map(|v| v.to_string()).ok_or_else(|| ArgError::MissingValue(name.to_string()))
        };
        let bad = |v: &str| ArgError::BadValue { option: name.to_string(), value: v.to_string() };
        match name {
            "-h" | "--help" => opts.help = true,
            "--level" => {
                let v = value(&mut i)?;
                opts.level = v.parse().map_err(|_| bad(&v))?;
            }
            "--top" => {
                let v = value(&mut i)?;
                opts.top = match v.parse::<usize>() {
                    Ok(n) if n >= 1 => n,
                    _ => return Err(bad(&v)),
                };
            }
            "--source" => {
                let v = value(&mut i)?;
                opts.sources.push(v);
            }
            _ => return Err(ArgError::Unknown(arg.to_string())),
        }
        i += 1;
    }
    Ok(opts)
}

// ---- the summariser ----

impl fmt::Display for Level {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.pad(match self {
            Level::Debug => "DEBUG",
            Level::Info => "INFO",
            Level::Warn => "WARN",
            Level::Error => "ERROR",
        })
    }
}

#[derive(Debug, Clone, PartialEq)]
struct Entry {
    time: String,
    level: Level,
    source: String,
    message: String,
}

#[derive(Debug, PartialEq)]
enum LineError {
    BadTimestamp(String),
    MissingLevel,
    UnknownLevel(String),
    MissingSource,
    MissingMessage,
}

impl fmt::Display for LineError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            LineError::BadTimestamp(w) => write!(f, "bad timestamp '{w}'"),
            LineError::MissingLevel => write!(f, "missing level"),
            LineError::UnknownLevel(w) => write!(f, "unknown level '{w}'"),
            LineError::MissingSource => write!(f, "missing source"),
            LineError::MissingMessage => write!(f, "missing message"),
        }
    }
}

/// Splits off the first whitespace-separated word, returning it and the rest.
fn next_word(s: &str) -> Option<(&str, &str)> {
    let s = s.trim_start();
    if s.is_empty() {
        return None;
    }
    Some(match s.find(char::is_whitespace) {
        Some(i) => (&s[..i], &s[i..]),
        None => (s, ""),
    })
}

fn valid_timestamp(t: &str) -> bool {
    let bytes = t.as_bytes();
    if bytes.len() != 19 {
        return false;
    }
    let shape = bytes.iter().enumerate().all(|(i, &c)| match i {
        4 | 7 => c == b'-',
        10 => c == b'T',
        13 | 16 => c == b':',
        _ => c.is_ascii_digit(),
    });
    if !shape {
        return false;
    }
    let num = |from: usize, to: usize| t[from..to].parse::<u32>().unwrap();
    (1..=12).contains(&num(5, 7)) && (1..=31).contains(&num(8, 10)) && num(11, 13) < 24 && num(14, 16) < 60 && num(17, 19) < 60
}

fn parse_line(line: &str) -> Result<Entry, LineError> {
    let (time, rest) = next_word(line).unwrap_or(("", ""));
    if !valid_timestamp(time) {
        return Err(LineError::BadTimestamp(time.to_string()));
    }
    let (word, rest) = next_word(rest).ok_or(LineError::MissingLevel)?;
    let level: Level = word.parse().map_err(|_| LineError::UnknownLevel(word.to_string()))?;
    let (word, rest) = next_word(rest).ok_or(LineError::MissingSource)?;
    let source = word
        .strip_prefix('[')
        .and_then(|w| w.strip_suffix(']'))
        .filter(|w| !w.is_empty())
        .ok_or(LineError::MissingSource)?;
    let message = rest.trim();
    if message.is_empty() {
        return Err(LineError::MissingMessage);
    }
    Ok(Entry { time: time.to_string(), level, source: source.to_string(), message: message.to_string() })
}

/// Replaces every run of digits with '#', so similar messages group together.
fn message_key(message: &str) -> String {
    let mut key = String::new();
    let mut in_digits = false;
    for c in message.chars() {
        if c.is_ascii_digit() {
            if !in_digits {
                key.push('#');
            }
            in_digits = true;
        } else {
            key.push(c);
            in_digits = false;
        }
    }
    key
}

fn plural(n: usize, one: &str, many: &str) -> String {
    format!("{n} {}", if n == 1 { one } else { many })
}

/// Counts the items and sorts them most common first, ties by name.
fn ranked<'a>(items: impl Iterator<Item = &'a str>) -> Vec<(&'a str, usize)> {
    let mut counts: HashMap<&str, usize> = HashMap::new();
    for item in items {
        *counts.entry(item).or_insert(0) += 1;
    }
    let mut ranked: Vec<(&str, usize)> = counts.into_iter().collect();
    ranked.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(b.0)));
    ranked
}

fn summarise(log: &str, options: &Options) -> Vec<String> {
    let mut entries = Vec::new();
    let mut malformed = Vec::new();
    for (i, line) in log.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        match parse_line(line) {
            Ok(entry) => entries.push(entry),
            Err(err) => malformed.push(format!("  line {}: {err}", i + 1)),
        }
    }

    let mut out = Vec::new();
    let mut read = format!("Read {}", plural(entries.len(), "entry", "entries"));
    if !malformed.is_empty() {
        read += &format!(" ({} skipped)", plural(malformed.len(), "malformed line", "malformed lines"));
    }
    out.push(read);

    let selected: Vec<&Entry> = entries
        .iter()
        .filter(|e| e.level >= options.level)
        .filter(|e| options.sources.is_empty() || options.sources.contains(&e.source))
        .collect();
    out.push(format!("Selected {}", plural(selected.len(), "entry", "entries")));

    if selected.is_empty() {
        out.push("Nothing to report.".to_string());
    } else {
        let first = selected.iter().map(|e| &e.time).min().unwrap();
        let last = selected.iter().map(|e| &e.time).max().unwrap();
        out.push(format!("From {first} to {last}"));

        out.push("By level:".to_string());
        let mut levels: BTreeMap<Level, usize> = BTreeMap::new();
        for e in &selected {
            *levels.entry(e.level).or_insert(0) += 1;
        }
        for (level, n) in levels.iter().rev() {
            out.push(format!("  {level:<5} {n}"));
        }

        out.push("By source:".to_string());
        let sources = ranked(selected.iter().map(|e| e.source.as_str()));
        let width = sources.iter().map(|(s, _)| s.chars().count()).max().unwrap_or(0);
        for (source, n) in &sources {
            out.push(format!("  {source:<width$}  {n}"));
        }

        out.push("Top messages:".to_string());
        let keys: Vec<String> = selected.iter().map(|e| message_key(&e.message)).collect();
        for (message, n) in ranked(keys.iter().map(|k| k.as_str())).into_iter().take(options.top) {
            out.push(format!("  {n}x {message}"));
        }
    }

    if !malformed.is_empty() {
        out.push("Malformed:".to_string());
        out.extend(malformed);
    }
    out
}

const USAGE: &str = "usage: [--level <debug|info|warn|error>] [--top <n>] [--source <name>]... [-h|--help]";

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).expect("could not read standard input");
    let (first, log) = input.split_once('\n').unwrap_or((input.as_str(), ""));
    let args: Vec<&str> = first.split_whitespace().collect();

    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());
    let lines = match parse_args(&args) {
        Err(e) => vec![format!("error: {e}"), USAGE.to_string()],
        Ok(options) if options.help => {
            vec![USAGE.to_string(), "Reads log lines after the first line and prints a summary.".to_string()]
        }
        Ok(options) => summarise(log, &options),
    };
    for line in lines {
        writeln!(out, "{line}").expect("could not write output");
    }
}
